/**
 * The pixel stickers of the design (`docs/design/prototypes/sticker-<name>.svg`, generated by
 * `docs/design/tools/stickers.py`). A manifest names one of them; a test keeps this list and the
 * files in sync in both directions.
 */
export const STICKER_NAMES = [
  'base64',
  'burn',
  'colour',
  'cron',
  'diff',
  'download',
  'expiry',
  'hash',
  'img-background',
  'img-convert',
  'img-crop',
  'img-exif',
  'img-pixel',
  'img-resize',
  'json',
  'jwt',
  'lorem',
  'mac',
  'markdown',
  'password',
  'paste',
  'pdf-compress',
  'pdf-merge',
  'pdf-protect',
  'pdf-rotate',
  'pdf-split',
  'qr',
  'regex',
  'report',
  'shield',
  'site',
  'sql',
  'subnet',
  'textops',
  'timestamp',
  'trash',
  'units',
  'url',
  'useragent',
  'uuid',
  'xml',
  'yaml',
] as const;

export type StickerName = (typeof STICKER_NAMES)[number];

export function isStickerName(value: unknown): value is StickerName {
  return (STICKER_NAMES as readonly unknown[]).includes(value);
}
